from solution import max_subarray_product


def test_issue_example_given():
    """Maximum product subarray of [1, -2, -3, 0, 7, -8, -2] is 112."""
    assert max_subarray_product([1, -2, -3, 0, 7, -8, -2]) == 112  # 7*-8*-2 = 112


def test_issue_all_positive():
    """Maximum product subarray of all positives is their product."""
    assert max_subarray_product([1, 2, 3, 4]) == 24  # 1*2*3*4 = 24


def test_issue_two_negatives_make_positive():
    """Maximum product subarray of [-2, -3] is 6."""
    assert max_subarray_product([-2, -3]) == 6  # -2*-3 = 6


def test_issue_zero_is_max_when_rest_negative():
    """Maximum product subarray of [-2, 0, -1] is 0."""
    assert max_subarray_product([-2, 0, -1]) == 0  # max(-2, 0, -1, -2*0, 0*-1) = 0


def test_issue_single_positive():
    """Maximum product subarray of [5] is 5."""
    assert max_subarray_product([5]) == 5  # single element 5 = 5


def test_issue_single_negative():
    """Maximum product subarray of [-3] is -3."""
    assert max_subarray_product([-3]) == -3  # single element -3 = -3


def test_issue_single_zero():
    """Maximum product subarray of [0] is 0."""
    assert max_subarray_product([0]) == 0  # single element 0 = 0


def test_issue_odd_negatives_best_drops_one():
    """Maximum product subarray of [-2, -3, -4] is 12."""
    assert max_subarray_product([-2, -3, -4]) == 12  # -3*-4 = 12


def test_issue_negative_splits_array():
    """Maximum product subarray of [2, 3, -2, 4] is 6."""
    assert max_subarray_product([2, 3, -2, 4]) == 6  # 2*3 = 6


def test_issue_whole_array_with_two_negatives():
    """Maximum product subarray of [-2, 3, -4] is 24."""
    assert max_subarray_product([-2, 3, -4]) == 24  # -2*3*-4 = 24


def test_issue_leading_zero():
    """Maximum product subarray of [0, 2, 3] is 6."""
    assert max_subarray_product([0, 2, 3]) == 6  # 2*3 = 6
